from collections import deque
cells={(3,r) for r in range(6)} | {(c,3) for c in range(4)} | {(c,4) for c in range(4)} | {(c,5) for c in range(4)} | {(3,6)}
pegs=frozenset({(2,3),(1,4),(1,5),(2,5),(3,5),(3,6)})
def moves(p):
    for c,r in p:
        for dc,dr in [(2,0),(-2,0),(0,2),(0,-2)]:
            mid=(c+dc//2,r+dr//2); dst=(c+dc,r+dr)
            if mid in cells and dst in cells and dst not in p:
                q=(p-{(c,r)})|{dst}
                if mid in p:q=q-{mid}
                yield ((c,r),dst,mid in p),frozenset(q)
q=deque([pegs]); prev={pegs:None}; pmove={}
goal=None
while q:
    p=q.popleft()
    if len(p)==1:goal=p;break
    for m,n in moves(p):
        if n not in prev:prev[n]=p;pmove[n]=m;q.append(n)
path=[]
p=goal
while prev[p] is not None:path.append(pmove[p]);p=prev[p]
path=path[::-1]
print(len(path),path)
print(goal)
